7	#include <algorithm>
8	#include <cstdint>
9	#include <cmath>
10	
11	#include <torch/extension.h>
12	#include <torch/library.h>
13	
14	#include "torch_kernel_helper.h"
15	#include "tiling/platform/platform_ascendc.h"
16	
17	#include "aclrtlaunch_foreach_pow_scalar.h"
18	
19	namespace ascend_kernel {
20	
21	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
22	constexpr int64_t kCacheLineSize = 512;
23	
24	static bool isOddInteger(float val)
25	{
26	    int ival = static_cast<int>(val);
27	    if (static_cast<float>(ival) != val) return false;
28	    return (ival & 1) != 0;
29	}
30	
31	at::Tensor foreach_pow_scalar(const at::Tensor &x, double exponent)
32	{
33	    TORCH_CHECK(x.dtype() == at::kFloat || x.dtype() == at::kHalf ||
34	                   x.dtype() == at::kBFloat16 || x.dtype() == at::kInt,
35	        "foreach_pow_scalar: unsupported dtype, expected float32, float16, bfloat16, or int32");
36	    TORCH_CHECK(x.is_contiguous(), "foreach_pow_scalar: input must be contiguous");
37	
38	    auto xContig = x.contiguous();
39	    auto dtype = x.scalar_type();
40	
41	    int64_t dtypeFlag = 0;
42	    if (dtype == at::kHalf) {
43	        dtypeFlag = 1;
44	    } else if (dtype == at::kBFloat16) {
45	        dtypeFlag = 2;
46	    } else if (dtype == at::kInt) {
47	        dtypeFlag = 3;
48	    }
49	
50	    // Determine signMode from exponent
51	    float expValFloat = static_cast<float>(exponent);
52	    float expValFloor = std::floor(expValFloat);
53	    bool isIntegerExp = (expValFloat == expValFloor);
54	    int32_t signMode = 0;  // default: even integer or no sign change needed
55	    if (isIntegerExp) {
56	        if (isOddInteger(expValFloat)) {
57	            signMode = 1;  // odd integer: negate negative bases
58	        }
59	        // else: even integer: signMode = 0 (positive result, absPow is correct)
60	    } else {
61	        signMode = 2;  // non-integer: NaN for negative bases
62	    }
63	
64	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
65	    int32_t coreNum = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());
66	    coreNum = std::min<int32_t>(coreNum, DEFAULT_NUM_PHYSICAL_CORES);
67	    if (coreNum <= 0) coreNum = 1;
68	
69	    uint64_t ubSizeVal;
70	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSizeVal);
71	    int64_t ubSize = static_cast<int64_t>(ubSizeVal);
72	
73	    int64_t totalLen = xContig.numel();
74	    int32_t dtypeSize = static_cast<int32_t>(c10::elementSize(dtype));
75	
76	    // UB tile length calculation:
77	    // fp16/bf16: inQueue(2B) + outQueue(2B) + castBuf(4) + outCastBuf(4) + w0(4) + w1(4) + w2(4) = 24 bytes/elem
78	    // fp32:      inQueue(4B) + outQueue(4B) + w0(4) + w1(4) + w2(4) = 20 bytes/elem
79	    // int32:     inQueue(4B) + outQueue(4B) + castBuf(4) + outCastBuf(4) + w0(4) + w1(4) + w2(4) = 28 bytes/elem
80	    int64_t bytesPerElem = 32;  // conservative: covers all dtype paths
81	    int64_t kDataUbBudget = ubSize * 3 / 10;
82	    int32_t tileLen = static_cast<int32_t>(kDataUbBudget / bytesPerElem);
83	    tileLen = (tileLen / 32) * 32;
84	    if (tileLen < 32) tileLen = 32;
85	    if (tileLen > 8192) tileLen = 8192;
86	
87	    // Block-level partition with cache line alignment
88	    int32_t elemPerCL = static_cast<int32_t>(kCacheLineSize / dtypeSize);
89	    if (elemPerCL < 1) elemPerCL = 256;
90	    int32_t elemsPerBlock = static_cast<int32_t>((totalLen + coreNum - 1) / coreNum);
91	    elemsPerBlock = ((elemsPerBlock + elemPerCL - 1) / elemPerCL) * elemPerCL;
92	    if (elemsPerBlock < elemPerCL) elemsPerBlock = elemPerCL;
93	
94	    int32_t formerNum = static_cast<int32_t>(totalLen / elemsPerBlock);
95	    int32_t formerLen = elemsPerBlock;
96	    int32_t tailLen = static_cast<int32_t>(totalLen % elemsPerBlock);
97	    int32_t tailNum = (tailLen > 0) ? 1 : 0;
98	
99	    int32_t numTilesPerBlock = static_cast<int32_t>((elemsPerBlock + tileLen - 1) / tileLen);
100	
101	    auto yOut = at::empty_like(xContig);
102	
103	    // All params as left values for EXEC_KERNEL_CMD
104	    int32_t totalLenI32 = static_cast<int32_t>(totalLen);
105	    uint32_t blockDim = static_cast<uint32_t>(formerNum + tailNum);
106	    int32_t dtypeFlagI32 = static_cast<int32_t>(dtypeFlag);
107	    float expValLeftVal = expValFloat;
108	    int32_t signModeI32 = signMode;
109	
110	    EXEC_KERNEL_CMD(foreach_pow_scalar, blockDim,
111	                    xContig, yOut,
112	                    totalLenI32, tileLen,
113	                    formerNum, formerLen, tailNum, tailLen,
114	                    elemsPerBlock, numTilesPerBlock,
115	                    expValLeftVal, signModeI32, dtypeFlagI32);
116	
117	    return yOut;
118	}
119	
120	}  // namespace ascend_kernel
121

1	/*
2	 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
