5	 */
6	
7	// ForeachPowScalar: element-wise power Y = X ^ exponent
8	// Computed via Abs/Ln/Muls/Exp chain following ForeachErf kernel pattern.
9	
10	#include "kernel_operator.h"
11	
12	constexpr int32_t BUFFER_NUM = 1;
13	
14	// ---------------------------------------------------------------------------
15	// GM <-> UB helpers (from ForeachErf)
16	// ---------------------------------------------------------------------------
17	
18	template <typename T>
19	__aicore__ inline void LoadGmToUb(
20	    AscendC::LocalTensor<T> &dst,
21	    AscendC::GlobalTensor<T> src,
22	    uint32_t count)
23	{
24	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
25	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
26	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
27	}
28	
29	template <typename T>
30	__aicore__ inline void StoreUbToGm(
31	    AscendC::GlobalTensor<T> dst,
32	    AscendC::LocalTensor<T> &src,
33	    uint32_t count)
34	{
35	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
36	    AscendC::DataCopyPad(dst, src, copyParams);
37	}
38	
39	// ---------------------------------------------------------------------------
40	// Precision helpers (from ForeachErf)
41	// ---------------------------------------------------------------------------
42	
43	template <typename T>
44	__aicore__ inline void PrepareInputTensor(
45	    AscendC::LocalTensor<float> &dst,
46	    AscendC::LocalTensor<T> &src,
47	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
48	    int32_t count)
49	{
50	    if constexpr (std::is_same_v<T, float>) {
51	        dst = src.template ReinterpretCast<float>();
52	    } else {
53	        dst = castBuf.Get<float>();
54	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
55	        AscendC::PipeBarrier<PIPE_V>();
56	    }
57	}
58	
59	template <typename T>
60	__aicore__ inline void PrepareOutputTensor(
61	    AscendC::LocalTensor<float> &dst,
62	    AscendC::LocalTensor<T> &out,
63	    AscendC::TBuf<AscendC::TPosition::VECCALC> &outCastBuf)
64	{
65	    if constexpr (std::is_same_v<T, float>) {
66	        dst = out.template ReinterpretCast<float>();
67	    } else {
68	        dst = outCastBuf.Get<float>();
69	    }
70	}
71	
72	// =========================================================================
73	// Main kernel
74	// =========================================================================
75	
76	template <typename dataType>
77	class KernelForeachPowScalar {
78	public:
79	    __aicore__ inline void Init(
80	        GM_ADDR xGm, GM_ADDR yGm,
81	        int32_t totalLength, int32_t tileLength,
82	        int32_t formerNum, int32_t formerLength,
83	        int32_t tailNum, int32_t tailLength,
84	        int32_t elementsPerBlock, int32_t numTilesPerBlock,
85	        float expVal)
86	    {
87	        totalLen_ = totalLength;
88	        N_ = tileLength;
89	        formerNum_ = formerNum;
90	        formerLength_ = formerLength;
91	        tailNum_ = tailNum;
92	        tailLength_ = tailLength;
93	        elemsPerBlock_ = elementsPerBlock;
94	        tilesPerBlock_ = numTilesPerBlock;
95	        expVal_ = expVal;
96	
97	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(xGm), totalLen_);
98	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(yGm), totalLen_);
99	
100	        if ASCEND_IS_AIV {
101	            pipe.InitBuffer(inQueue_, BUFFER_NUM, N_ * sizeof(dataType));
102	            pipe.InitBuffer(outQueue_, BUFFER_NUM, N_ * sizeof(dataType));
103	
104	            if constexpr (!std::is_same_v<dataType, float>) {
105	                pipe.InitBuffer(castBuf_, N_ * sizeof(float));
106	                pipe.InitBuffer(outCastBuf_, N_ * sizeof(float));
107	            } else {
108	                pipe.InitBuffer(tmpBuf_, N_ * sizeof(float));
109	            }
110	
111	            // Work buffers for pow chain
112	            pipe.InitBuffer(w0Buf_, N_ * sizeof(float));
113	            pipe.InitBuffer(w1Buf_, N_ * sizeof(float));
114	        }
115	    }
116	
117	    __aicore__ inline void Process()
118	    {
119	        if ASCEND_IS_AIV {
120	            int32_t coreIdx = AscendC::GetBlockIdx();
121	            int32_t blockOffset;
122	
123	            if (coreIdx < formerNum_) {
124	                blockOffset = coreIdx * formerLength_;
125	            } else if (tailNum_ > 0 && coreIdx == formerNum_) {
126	                blockOffset = formerNum_ * formerLength_;
127	            } else {
128	                return;
129	            }
130	
131	            for (int32_t t = 0; t < tilesPerBlock_; ++t) {
132	                int32_t tileStart = blockOffset + t * N_;
133	                int32_t curLen = N_;
134	                if (tileStart + curLen > totalLen_) {
135	                    curLen = totalLen_ - tileStart;
136	                    if (curLen <= 0) continue;
137	                }
138	                int32_t blockEnd = blockOffset + elemsPerBlock_;
139	                if (blockEnd > totalLen_) blockEnd = totalLen_;
140	                if (tileStart >= blockEnd) continue;
141	                if (tileStart + curLen > blockEnd) {
142	                    curLen = blockEnd - tileStart;
143	                }
144	
145	                CopyIn(tileStart, curLen);
146	                Compute(curLen);
147	                CopyOut(tileStart, curLen);
148	            }
149	        }
150	    }
151	
152	private:
153	    __aicore__ inline void CopyIn(int32_t start, int32_t count)
154	    {
155	        xInLocal_ = inQueue_.AllocTensor<dataType>();
156	        LoadGmToUb(xInLocal_, xGM_[start], static_cast<uint32_t>(count));
157	        inQueue_.EnQue(xInLocal_);
158	    }
159	
160	    __aicore__ inline void Compute(int32_t count)
161	    {
162	        xInLocal_ = inQueue_.DeQue<dataType>();
163	
164	        yOutLocal_ = outQueue_.AllocTensor<dataType>();
165	        PrepareOutputTensor<dataType>(yFp32Local_, yOutLocal_, outCastBuf_);
166	        PrepareInputTensor<dataType>(xFp32Local_, xInLocal_, castBuf_, count);
167	
168	        // Get work buffers
169	        auto w0 = w0Buf_.Get<float>();
170	        auto w1 = w1Buf_.Get<float>();
171	
172	        // Step 1: Abs(x) -> w0
173	        AscendC::Abs(w0, xFp32Local_, static_cast<uint32_t>(count));
174	        AscendC::PipeBarrier<PIPE_V>();
175	
176	        // Step 2: Ln(|x|) -> w0 (overwrite)
177	        AscendC::Ln(w0, w0, static_cast<uint32_t>(count));
178	        AscendC::PipeBarrier<PIPE_V>();
179	
180	        // Step 3: Multiply by exponent -> w0 (overwrite)
181	        AscendC::Muls(w0, w0, expVal_, static_cast<uint32_t>(count));
182	        AscendC::PipeBarrier<PIPE_V>();
183	
184	        // Step 4: Exp -> w1 = |x|^exponent
185	        AscendC::Exp(w1, w0, static_cast<uint32_t>(count));
186	        AscendC::PipeBarrier<PIPE_V>();
187	
188	        // Copy result from w1 to output fp32 buffer
189	        AscendC::DataCopy(yFp32Local_, w1, static_cast<uint32_t>(count));
190	
191	        // Cast back to original dtype if needed
192	        if constexpr (!std::is_same_v<dataType, float>) {
193	            AscendC::Cast(yOutLocal_, yFp32Local_,
194	                          AscendC::RoundMode::CAST_NONE, count);
195	            AscendC::PipeBarrier<PIPE_V>();
196	        }
197	
198	        outQueue_.EnQue(yOutLocal_);
199	        inQueue_.FreeTensor(xInLocal_);
200	    }
201	
202	    __aicore__ inline void CopyOut(int32_t start, int32_t count)
203	    {
204	        yOutLocal_ = outQueue_.DeQue<dataType>();
205	        StoreUbToGm(yGM_[start], yOutLocal_, static_cast<uint32_t>(count));
206	        outQueue_.FreeTensor(yOutLocal_);
207	    }
208	
209	private:
210	    AscendC::TPipe pipe;
211	    int32_t totalLen_, N_;
212	    int32_t formerNum_, formerLength_, tailNum_, tailLength_;
213	    int32_t elemsPerBlock_, tilesPerBlock_;
214	    float expVal_;
215	
216	    AscendC::GlobalTensor<dataType> xGM_, yGM_;
217	
218	    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> inQueue_;
219	    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> outQueue_;
220	
221	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;
222	    AscendC::TBuf<AscendC::TPosition::VECCALC> outCastBuf_;
223	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
224	    AscendC::TBuf<AscendC::TPosition::VECCALC> w0Buf_;
225	    AscendC::TBuf<AscendC::TPosition::VECCALC> w1Buf_;
226	
227	    AscendC::LocalTensor<dataType> xInLocal_;
228	    AscendC::LocalTensor<dataType> yOutLocal_;
229	
230	    AscendC::LocalTensor<float> xFp32Local_;
231	    AscendC::LocalTensor<float> yFp32Local_;
232	};
233	
234	extern "C" __global__ __aicore__ void foreach_pow_scalar(
235	    GM_ADDR xGm, GM_ADDR yGm,
236	    int32_t totalLength, int32_t tileLength,
237	    int32_t formerNum, int32_t formerLength,
238	    int32_t tailNum, int32_t tailLength,
239	    int32_t elementsPerBlock, int32_t numTilesPerBlock,
240	    float expVal, int32_t signMode,
241	    int32_t dtypeFlag)
242	{
243	    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);
244	
245	    if (dtypeFlag == 0) {
246	        KernelForeachPowScalar<float> kernel;
247	        kernel.Init(xGm, yGm,
248	                    totalLength, tileLength, formerNum, formerLength,
249	                    tailNum, tailLength, elementsPerBlock, numTilesPerBlock,
250	                    expVal);
251	        kernel.Process();
252	    } else if (dtypeFlag == 1) {
253	        KernelForeachPowScalar<half> kernel;
254	        kernel.Init(xGm, yGm,
255	                    totalLength, tileLength, formerNum, formerLength,
256	                    tailNum, tailLength, elementsPerBlock, numTilesPerBlock,
257	                    expVal);
258	        kernel.Process();
259	    } else {
260	        KernelForeachPowScalar<bfloat16_t> kernel;
261	        kernel.Init(xGm, yGm,
262	                    totalLength, tileLength, formerNum, formerLength,
263	                    tailNum, tailLength, elementsPerBlock, numTilesPerBlock,
264	                    expVal);
265	        kernel.Process();
266	    }
267	}
