// ForeachMinimumScalar: element-wise minimum Y = min(X, scalar)
// Computed via Cast to fp32, Mins, Cast back.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// GM <-> UB helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// ---------------------------------------------------------------------------
// Precision helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void PrepareInputTensor(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void PrepareOutputTensor(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &out,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &outCastBuf)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = out.template ReinterpretCast<float>();
    } else {
        dst = outCastBuf.Get<float>();
    }
}

// =========================================================================
// Main kernel
// =========================================================================

template <typename dataType>
class KernelForeachMinimumScalar {
public:
    __aicore__ inline void Init(
        GM_ADDR xGm, GM_ADDR yGm,
        int32_t totalLength, int32_t tileLength,
        int32_t formerNum, int32_t formerLength,
        int32_t tailNum, int32_t tailLength,
        int32_t elementsPerBlock, int32_t numTilesPerBlock,
        float scalarVal)
    {
        totalLen_ = totalLength;
        N_ = tileLength;
        formerNum_ = formerNum;
        formerLength_ = formerLength;
        tailNum_ = tailNum;
        tailLength_ = tailLength;
        elemsPerBlock_ = elementsPerBlock;
        tilesPerBlock_ = numTilesPerBlock;
        scalarVal_ = scalarVal;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(xGm), totalLen_);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(yGm), totalLen_);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(inQueue_, BUFFER_NUM, N_ * sizeof(dataType));
            pipe.InitBuffer(outQueue_, BUFFER_NUM, N_ * sizeof(dataType));

            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(castBuf_, N_ * sizeof(float));
                pipe.InitBuffer(outCastBuf_, N_ * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t coreIdx = AscendC::GetBlockIdx();
            int32_t blockOffset;

            if (coreIdx < formerNum_) {
                blockOffset = coreIdx * formerLength_;
            } else if (tailNum_ > 0 && coreIdx == formerNum_) {
                blockOffset = formerNum_ * formerLength_;
            } else {
                return;
            }

            for (int32_t t = 0; t < tilesPerBlock_; ++t) {
                int32_t tileStart = blockOffset + t * N_;
                int32_t curLen = N_;
                if (tileStart + curLen > totalLen_) {
                    curLen = totalLen_ - tileStart;
                    if (curLen <= 0) continue;
                }
                int32_t blockEnd = blockOffset + elemsPerBlock_;
                if (blockEnd > totalLen_) blockEnd = totalLen_;
                if (tileStart >= blockEnd) continue;
                if (tileStart + curLen > blockEnd) {
                    curLen = blockEnd - tileStart;
                }

                CopyIn(tileStart, curLen);
                Compute(curLen);
                CopyOut(tileStart, curLen);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t start, int32_t count)
    {
        xInLocal_ = inQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[start], static_cast<uint32_t>(count));
        inQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void Compute(int32_t count)
    {
        xInLocal_ = inQueue_.DeQue<dataType>();

        yOutLocal_ = outQueue_.AllocTensor<dataType>();
        PrepareOutputTensor<dataType>(yFp32Local_, yOutLocal_, outCastBuf_);
        PrepareInputTensor<dataType>(xFp32Local_, xInLocal_, castBuf_, count);

        // Compute: y = min(x, scalar)
        AscendC::Mins(yFp32Local_, xFp32Local_, scalarVal_, static_cast<uint32_t>(count));

        // Cast back to original dtype if needed
        if constexpr (!std::is_same_v<dataType, float>) {
            AscendC::Cast(yOutLocal_, yFp32Local_,
                          AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
        }

        outQueue_.EnQue(yOutLocal_);
        inQueue_.FreeTensor(xInLocal_);
    }

    __aicore__ inline void CopyOut(int32_t start, int32_t count)
    {
        yOutLocal_ = outQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[start], yOutLocal_, static_cast<uint32_t>(count));
        outQueue_.FreeTensor(yOutLocal_);
    }

private:
    AscendC::TPipe pipe;
    int32_t totalLen_, N_;
    int32_t formerNum_, formerLength_, tailNum_, tailLength_;
    int32_t elemsPerBlock_, tilesPerBlock_;
    float scalarVal_;

    AscendC::GlobalTensor<dataType> xGM_, yGM_;

    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> inQueue_;
    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> outQueue_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;

    AscendC::LocalTensor<float> xFp32Local_;
    AscendC::LocalTensor<float> yFp32Local_;
};

extern "C" __global__ __aicore__ void foreach_minimum_scalar(
    GM_ADDR xGm, GM_ADDR yGm,
    int32_t totalLength, int32_t tileLength,
    int32_t formerNum, int32_t formerLength,
    int32_t tailNum, int32_t tailLength,
    int32_t elementsPerBlock, int32_t numTilesPerBlock,
    float scalarVal,
    int32_t dtypeFlag)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);

    if (dtypeFlag == 0) {
        KernelForeachMinimumScalar<float> kernel;
        kernel.Init(xGm, yGm,
                    totalLength, tileLength, formerNum, formerLength,
                    tailNum, tailLength, elementsPerBlock, numTilesPerBlock,
                    scalarVal);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        KernelForeachMinimumScalar<half> kernel;
        kernel.Init(xGm, yGm,
                    totalLength, tileLength, formerNum, formerLength,
                    tailNum, tailLength, elementsPerBlock, numTilesPerBlock,
                    scalarVal);
        kernel.Process();
    } else if (dtypeFlag == 2) {
        KernelForeachMinimumScalar<bfloat16_t> kernel;
        kernel.Init(xGm, yGm,
                    totalLength, tileLength, formerNum, formerLength,
                    tailNum, tailLength, elementsPerBlock, numTilesPerBlock,
                    scalarVal);
        kernel.Process();
    } else {
        // dtypeFlag == 3: int32
        KernelForeachMinimumScalar<int32_t> kernel;
        kernel.Init(xGm, yGm,
                    totalLength, tileLength, formerNum, formerLength,
                    tailNum, tailLength, elementsPerBlock, numTilesPerBlock,
                    scalarVal);
        kernel.Process();
    }
}
